solution.Program.cs:
using System.Globalization;

var inv = CultureInfo.InvariantCulture;
decimal balance = 0;
var history = new List<string>();

string Money(decimal amount) => amount.ToString("F2", inv);

while (true)
{
    Console.Write("> ");
    string? line = Console.ReadLine();
    if (line == null) break;
    string[] words = line.Split(' ', StringSplitOptions.RemoveEmptyEntries);
    if (words.Length == 0) continue;
    string command = words[0].ToLowerInvariant();

    if (command == "quit") break;

    switch (command)
    {
        case "balance":
            Console.WriteLine($"Balance: {Money(balance)}");
            continue;
        case "history":
            if (history.Count == 0) Console.WriteLine("No transactions.");
            for (int i = 0; i < history.Count; i++) Console.WriteLine($"{i + 1}. {history[i]}");
            continue;
        case "deposit":
        case "withdraw":
        case "interest":
            break;
        default:
            Console.WriteLine($"Unknown command: {words[0]}");
            continue;
    }

    if (words.Length != 2)
    {
        Console.WriteLine($"Usage: {command} <amount>");
        continue;
    }
    bool parsed = decimal.TryParse(words[1], NumberStyles.Number, inv, out decimal amount);
    if (command != "interest") amount = Math.Round(amount, 2, MidpointRounding.AwayFromZero);
    bool valid = parsed && (command == "interest" ? amount >= 0 : amount > 0);
    if (!valid)
    {
        Console.WriteLine("Amount must be a positive number.");
        continue;
    }

    switch (command)
    {
        case "deposit":
            balance += amount;
            history.Add($"deposit {Money(amount)}");
            Console.WriteLine($"Deposited {Money(amount)}. Balance: {Money(balance)}");
            break;
        case "withdraw":
            if (amount > balance)
            {
                Console.WriteLine($"Not enough money. Balance: {Money(balance)}");
                break;
            }
            balance -= amount;
            history.Add($"withdraw {Money(amount)}");
            Console.WriteLine($"Withdrew {Money(amount)}. Balance: {Money(balance)}");
            break;
        case "interest":
            decimal added = Math.Round(balance * amount / 100, 2, MidpointRounding.AwayFromZero);
            balance += added;
            history.Add($"interest {Money(added)}");
            Console.WriteLine($"Added interest {Money(added)}. Balance: {Money(balance)}");
            break;
    }
}

Console.WriteLine($"Goodbye. Final balance: {Money(balance)}");
